package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamDemocracyBank2 {
  private const val T = "ප්‍රජාතන්ත්‍රවාදය, පුරවැසිභාවය හා ආණ්ඩු ක්‍රම"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ජෝන් ලොක්ගේ සමාජ ගිවිසුම් න්‍යාය අනුව මිනිසුන්ට උපතින්ම හිමිවන ස්වාභාවික අයිතිවාසිකම් තුන කවරේද?", "ජීවිතය, නිදහස සහ දේපළ", "බලය, ධනය සහ කීර්තිය", "යුද්ධය, සාමය සහ ආඥාව", "කුලය, ආගම සහ භාෂාව", "ජෝන් ලොක් ජීවිතය, නිදහස හා දේපළ අයිතිය ස්වාභාවික අයිතීන් ලෙස දැක්වීය."),
    q("'සමාජ ගිවිසුම' (The Social Contract) නමැති ප්‍රකට දේශපාලන දර්ශන ග්‍රන්ථය රචනා කළේ කවුද?", "ජීන් ජැක් රූසෝ", "කාල් මාක්ස්", "ඇඩම් ස්මිත්", "නිකොලෝ මැකියාවෙලි", "ප්‍රංශ චින්තක ජීන් ජැක් රූසෝ 1762 දී 'සමාජ ගිවිසුම' ග්‍රන්ථය රචනා කළේය."),
    q("වෙස්ට්මින්ස්ටර් පාර්ලිමේන්තු ආණ්ඩු ක්‍රමයේ නිජබිම ලෙස සැලකෙන රට කුමක්ද?", "එක්සත් රාජධානිය", "ඇමරිකා එක්සත් ජනපදය", "ස්විට්සර්ලන්තය", "රුසියාව", "ලන්ඩන්හි වෙස්ට්මින්ස්ටර් මාලිගයේ පාර්ලිමේන්තු සම්ප්‍රදාය මත මෙම ක්‍රමය බිහිවිය."),
    q("සන්ධීය ආණ්ඩු ක්‍රමයක පවතින ප්‍රධාන වාසියක් වන්නේ කුමක්ද?", "විශාල හා විවිධත්වයෙන් යුත් රටක ප්‍රාදේශීය අනන්‍යතා සුරැකීම", "එක් නායකයෙකුට සියලු බලතල තනිව පැවරීම", "ප්‍රාන්ත ආණ්ඩු සම්පූර්ණයෙන් අහෝසි කිරීම", "මැතිවරණ පැවැත්වීම නතර කිරීම", "ඉන්දියාව හා ඇමරිකාව වැනි විශාල රටවල විවිධ ජන කොටස් එකට රඳවා ගැනීමට සන්ධීය ක්‍රමය උපකාරී වේ."),
    q("ඒකීය ආණ්ඩු ක්‍රමයක පවතින ප්‍රධාන වාසියක් වන්නේ කුමක්ද?", "රට පුරා ඒකාකාර නීති පද්ධතියක් හා පාලන සමගියක් පැවතීම", "සෑම ප්‍රාන්තයකටම වෙනම ජාතික හමුදාවක් තිබීම", "ප්‍රාන්ත වෙනම රටවල් ලෙස වෙන්වීම", "මධ්‍යම පාර්ලිමේන්තුවට බලයක් නොමැති වීම", "කුඩා හා සංයුක්ත රටවල පරිපාලන වියදම් අවම කර ඒකීය නීති පවත්වා ගැනීමට මෙය පහසු වේ."),
    q("පහත සඳහන් රටවල් අතරින් කැබිනට් පාර්ලිමේන්තු ආණ්ඩු ක්‍රමයක් ක්‍රියාත්මක වන රට කුමක්ද?", "ඉන්දියාව", "ඇමරිකා එක්සත් ජනපදය", "බ්‍රසීලය", "මෙක්සිකෝව", "ඉන්දියාවේ අගමැති ප්‍රමුඛ කැබිනට් මණ්ඩලය පාර්ලිමේන්තුවට වගකියන පාර්ලිමේන්තු ක්‍රමයක් පවතී."),
    q("ඇමරිකා එක්සත් ජනපදයේ ක්‍රියාත්මක වන ආණ්ඩු ආකෘතිය කුමක්ද?", "සන්ධීය ජනාධිපති ක්‍රමය", "ඒකීය පාර්ලිමේන්තු ක්‍රමය", "ව්‍යවස්ථාපිත රාජාණ්ඩු ක්‍රමය", "සමාජවාදී ඒකපාක්ෂික ක්‍රමය", "ඇමරිකාව ප්‍රාන්ත 50ක සන්ධීය රාජ්‍යයක් මෙන්ම ජනාධිපති ක්‍රමයක් ක්‍රියාත්මක කරන රටකි."),
    q("වර්තමානයේ චීනයේ ක්‍රියාත්මක වන දේශපාලන පක්ෂ ක්‍රමය කුමක්ද?", "ඒකපාක්ෂික ක්‍රමය", "ද්විපාක්ෂික ක්‍රමය", "නිර්පාක්ෂික රාජාණ්ඩුව", "බහුපාක්ෂික සන්ධාන ක්‍රමය", "චීන කොමියුනිස්ට් පක්ෂය ප්‍රමුඛ ඒකපාක්ෂික පාලනයක් එහි ක්‍රියාත්මක වේ."),
    q("ශ්‍රී ලංකාව තුළ දීර්ඝ කාලයක් පුරා ක්‍රියාත්මක වන දේශපාලන පක්ෂ ක්‍රමය කුමක්ද?", "බහුපාක්ෂික ක්‍රමය", "ඒකපාක්ෂික ක්‍රමය", "හමුදා ජුන්ටා ක්‍රමය", "පක්ෂ රහිත රාජාණ්ඩුව", "දේශපාලන පක්ෂ රැසක් නිදහසේ මැතිවරණවලට තරග කරන බැවින් බහුපාක්ෂික ක්‍රමය ක්‍රියාත්මක වේ."),
    q("ප්‍රජාතන්ත්‍රවාදයේදී 'ප්‍රභූතන්ත්‍රවාදය' (Aristocracy) යන්නෙන් අදහස් කෙරෙන පාලන ක්‍රමය කුමක්ද?", "වංශවත් හෝ සුළු වරප්‍රසාදිත පිරිසක් විසින් පාලනය කිරීම", "සියලු වැඩිහිටි පුරවැසියන්ගේ ඡන්දයෙන් පාලනය කිරීම", "කිසිදු නීතියක් නොමැතිව අරාජිකව පාලනය කිරීම", "විදේශ හමුදාවක් විසින් පාලනය කිරීම", "සාමාන්‍ය ජනතාවට බලය නොමැතිව සුළු ප්‍රභූ පැලැන්තියක් පාලනය ගෙන යාමයි."),
    q("ආගමික නායකයන් හෝ පූජක පැලැන්තිය ආගමික නීති මත රට පාලනය කරන ආණ්ඩු ක්‍රමය කුමක්ද?", "දේවතන්ත්‍රවාදය", "නියෝජිත ප්‍රජාතන්ත්‍රවාදය", "ලෞකික සන්ධීය ක්‍රමය", "කාරක සභා ක්‍රමය", "ආගමික අධිකාරිය මත පදනම් වූ පාලන ක්‍රමය Theocracy ලෙස හැඳින්වේ."),
    q("රටක සියලු ආගම්වලට සමාන ගෞරවය දක්වමින් රාජ්‍ය පාලනය ආගමෙන් වෙන්කර තබන රාජ්‍ය ප්‍රතිපත්තිය කුමක්ද?", "ලෞකික රාජ්‍ය සංකල්පය", "දේවතන්ත්‍රවාදය", "සන්ධීය රාජාණ්ඩුව", "යටත්විජිත ප්‍රතිපත්තිය", "ආගමික මධ්‍යස්ථභාවය රකින පාලන ක්‍රමය Secular State ලෙස හැඳින්වේ."),
    q("ශ්‍රී ලංකාවේ 1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 9 වන වගන්තියෙන් ප්‍රකාශ කෙරෙන්නේ කුමක්ද?", "බුද්ධාගමට ප්‍රමුඛස්ථානය දෙමින් සෙසු ආගම්වල අයිතීන් සුරැකීම", "සියලු ආගම් තහනම් කිරීම", "රට සන්ධීය රාජ්‍යයක් බවට පත් කිරීම", "දෙමළ භාෂාව පමණක් රාජ්‍ය භාෂාව කිරීම", "9 වන වගන්තිය බුද්ධාගමට ප්‍රමුඛස්ථානය ලබාදෙන අතරම 10 හා 14(1)(ඉ) වගන්තිවලින් සියලු ආගම් රකී."),
    q("ශ්‍රී ලංකා ව්‍යවස්ථාවේ 18 වන වගන්තිය යටතේ රාජ්‍ය භාෂාවන් ලෙස පිළිගෙන ඇත්තේ කවර භාෂාද?", "සිංහල සහ දෙමළ", "සිංහල පමණි", "ඉංග්‍රීසි පමණි", "පාලි සහ සංස්කෘත", "1987 13 වන සංශෝධනයෙන් පසු සිංහල හා දෙමළ යන භාෂා දෙකම රාජ්‍ය භාෂා වන අතර ඉංග්‍රීසි සම්බන්ධීකරණ භාෂාව වේ."),
    q("ශ්‍රී ලංකාවේ ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 'සම්බන්ධීකරණ භාෂාව' (Link Language) ලෙස දක්වා ඇති භාෂාව කුමක්ද?", "ඉංග්‍රීසි භාෂාව", "සිංහල භාෂාව", "දෙමළ භාෂාව", "ප්‍රංශ භාෂාව", "ව්‍යවස්ථාවේ 18(3) වගන්තිය අනුව ඉංග්‍රීසි සම්බන්ධීකරණ භාෂාව වේ."),
    q("ශ්‍රී ලංකාවේ ජාතික භාෂා ලෙස ව්‍යවස්ථාවේ 19 වන වගන්තියෙන් පිළිගෙන ඇත්තේ මොනවාද?", "සිංහල සහ දෙමළ", "ඉංග්‍රීසි සහ ප්‍රංශ", "පාලි සහ දෙමළ", "හින්දි සහ ඉංග්‍රීසි", "සිංහල හා දෙමළ යන භාෂා දෙකම ශ්‍රී ලංකාවේ ජාතික භාෂාවන් වේ."),
    q("දරුවෙකු සතුටින්, ආරක්ෂිතව සහ නීතිගරුකව වැඩීමට පවුලෙන් ඉටුවන ප්‍රජාතන්ත්‍රවාදී කාර්යභාරය කුමක්ද?", "ප්‍රාථමික සමාජානුයෝජනය හා ගුණධර්ම ඉගැන්වීම", "ව්‍යවස්ථා සංශෝධන සම්මත කිරීම", "මැතිවරණ දිස්ත්‍රික්ක සීමා නිර්ණය", "විදේශ තානාපතිවරුන් පත් කිරීම", "පවුල තුළින් ඉවසීම, සමානාත්මතාව හා යුතුකම් පිළිබඳ මුල් අවබෝධය ලැබේ."),
    q("පුරවැසි අධ්‍යාපනය හැදෑරීමෙන් පාසල් සිසුවෙකු තුළ ඇතිවිය යුතු ප්‍රධානතම ප්‍රායෝගික වෙනස කුමක්ද?", "වගකීම් සහගත හා නීතිගරුක පුරවැසියෙකු බවට පත්වීම", "විභාග අංක පමණක් කටපාඩම් කිරීම", "රාජ්‍ය ආයතන කෙරෙහි උදාසීන වීම", "තම අයිතීන් පමණක් ඉල්ලා සිටීම", "දැනුම මත පදනම්ව සමාජ යුතුකම් ඉටුකරන සක්‍රිය පුරවැසියෙකු බිහි කිරීම මෙහි අරමුණයි."),
    q("ප්‍රජාතන්ත්‍රවාදී සමාජයක සාමූහික තීරණ ගැනීමේදී බහුතර කැමැත්ත විමසන විධිමත් ක්‍රමය කුමක්ද?", "ඡන්ද විමසීම", "අහඹු ලොතරැයි ඇදීම", "එක් අයෙකුගේ නියෝගය", "රහසිගත තරගාවලිය", "බහුතර මතය සාමකාමීව හඳුනාගැනීමට ඡන්ද විමසීම යොදා ගැනේ."),
    q("යහපත් නායකයෙකු තෝරාගැනීමේදී ඡන්දදායකයෙකු සැලකිලිමත් විය යුතු ප්‍රධානතම සාධකය කුමක්ද?", "අපේක්ෂකයාගේ අවංකභාවය, සුදුසුකම් හා ප්‍රතිපත්ති", "ලබාදෙන ක්ෂණික මුදල් හා භාණ්ඩ තෑගි", "පෞද්ගලික ඥාති සබඳතා පමණක්", "ප්‍රචණ්ඩකාරී කථන විලාසය", "රටේ යහපත උදෙසා දූෂණයෙන් තොර සුදුසු නායකත්වය තෝරාගැනීම ඡන්දදායක වගකීමකි."),
    q("රටේ සියලු පුරවැසියන්ට පොදු යහපත සඳහා දැනුම බෙදාදීම හා පර්යේෂණ කිරීම ඉටුකරන සමාජ ආයතනය කුමක්ද?", "අධ්‍යාපන ආයතන", "බන්ධනාගාර පද්ධතිය", "රේගු දෙපාර්තමේන්තුව", "විනිමය කොමිසම", "පාසල් හා විශ්වවිද්‍යාල බුද්ධිමත් පුරවැසි සමාජයක් ගොඩනගයි."),
    q("රටක ස්ථාවරභාවය හා සමාජ සාමය රඳා පවතින්නේ කුමන කරුණු දෙක සමතුලිත වීම මතද?", "පුරවැසි අයිතිවාසිකම් සහ පුරවැසි යුතුකම්", "ආනයන සහ විදේශ ණය", "හමුදා බලය සහ පුවත්පත් වාරණය", "පක්ෂ කාර්යාල සහ පෝස්ටර්", "අයිතීන් හා යුතුකම් සමබරව ඉටුවන විට සමාජ සාමය පවතී."),
    q("විධායක බලතල අධික ලෙස කේන්ද්‍රගත වීම වැළැක්වීම සඳහා ඇති හොඳම ව්‍යවස්ථාපිත ක්‍රමය කුමක්ද?", "ආයතන අතර තුලන හා සංවරණ ක්‍රමය", "පාර්ලිමේන්තුව විසුරුවා තැබීම", "ජනමාධ්‍ය ආයතන රජයට ගැනීම", "පළාත් සභා බලතල ඉවත් කිරීම", "ව්‍යවස්ථාදායකය, විධායකය හා අධිකරණය එකිනෙක පාලනය කිරීම තුලන හා සංවරණ ක්‍රමයයි."),
    q("ජාතික ආපදාවක් හෝ හදිසි තත්ත්වයක් ඇතිවූ විට රාජ්‍යය සමඟ එක්ව සහන සැලසීම පුරවැසියන්ගේ කවර ගුණාංගයක්ද?", "සමාජ වගකීම හා සහජීවනය", "ආර්ථික තරගකාරිත්වය", "පෞද්ගලික අයිතිවාසිකම් පැහැර ගැනීම", "දේශපාලන පක්ෂග්‍රාහීත්වය", "ආපදා අවස්ථාවලදී එකිනෙකාට උපකාර කිරීම සක්‍රිය පුරවැසි වගකීමකි."),
    q("ජනාධිපති ආණ්ඩු ක්‍රමයක ජනාධිපතිවරයා ධුර කාලය අතරතුර සාමාන්‍යයෙන් පාර්ලිමේන්තුවේ විශ්වාසභංගයකින් ඉවත් කළ නොහැකි වන්නේ ඇයි?", "ඔහු සෘජුවම ජනතා ඡන්දයෙන් නිශ්චිත කාලයකට පත්වන බැවින්", "ඔහුට කිසිදු නීතියක් අදාළ නොවන බැවින්", "පාර්ලිමේන්තුවක් එරට නොමැති බැවින්", "ඔහු හමුදාවේ අණදෙන නිලධාරී නොවන බැවින්", "සෘජු ජනවරමකින් පත්වන ජනාධිපතිවරයෙකු ඉවත් කළ හැක්කේ දෝෂාභියෝගයකින් පමණි."),
    q("පාර්ලිමේන්තු ආණ්ඩු ක්‍රමයක කැබිනට් මණ්ඩලය පාර්ලිමේන්තුවේ විශ්වාසය අහිමි වූ විට කුමක් කළ යුතුද?", "ඉල්ලා අස්වීම හෝ නව මැතිවරණයක් කැඳවීම", "අධිකරණය අහෝසි කිරීම", "මන්ත්‍රීවරුන් අත්අඩංගුවට ගැනීම", "ඡන්ද අයිතිය අවලංගු කිරීම", "පාර්ලිමේන්තු බහුතර විශ්වාසය නොමැති නම් විධායකයට බලයේ රැඳී සිටිය නොහැක."),
    q("ශ්‍රී ලංකාවේ රාජ්‍ය ලාංඡනයේ මුදුනින්ම දැක්වෙන සංකේතය කුමක්ද?", "ධර්ම චක්‍රය", "සිංහ රූපය", "පුන්කලස", "වී කරල් යුගල", "රාජ්‍ය ලාංඡනයේ ඉහළින්ම ධර්ම චක්‍රයද, මැද සිංහයා හා පුන්කලසද පිහිටා ඇත."),
    q("රාජ්‍ය ලාංඡනයේ පහළින්ම ඇති ඉර සහ හඳ සංකේතවත් කරන්නේ කුමක්ද?", "ඉර හඳ පවතින තුරු රටේ ස්ථිර පැවැත්ම", "කාලගුණ විද්‍යා දෙපාර්තමේන්තුව", "විදුලිබල උත්පාදනය", "මුහුදු වඩදිය බාදිය", "රට චිරාත් කාලයක් පවතින බව ඉර සහ හඳ මඟින් සංකේතවත් කෙරේ."),
    q("ශ්‍රී ලංකාවේ ජාතික පුෂ්පය ලෙස නිල වශයෙන් පිළිගෙන ඇත්තේ කුමක්ද?", "නිල් මානෙල් මල", "සුදු නෙළුම් මල", "අරලිය මල", "වෙසක් මල", "1986 දී නිල් මානෙල් මල ශ්‍රී ලංකාවේ ජාතික පුෂ්පය ලෙස ප්‍රකාශයට පත් කෙරිණි."),
    q("ශ්‍රී ලංකාවේ ජාතික වෘක්ෂය ලෙස නිල වශයෙන් නම් කර ඇත්තේ කුමන ගසද?", "නා ගස", "බෝ ගස", "තේක්ක ගස", "කොස් ගස", "1986 දී නා ගස (Mesua ferrea) ශ්‍රී ලංකාවේ ජාතික වෘක්ෂය ලෙස නම් කරන ලදී."),
    q("ශ්‍රී ලංකාවේ ජාතික පක්ෂියා ලෙස හඳුන්වනු ලබන්නේ කුමන පක්ෂියාද?", "වලිකුකුළා", "මොණරා", "හංසයා", "ගිරවා", "ශ්‍රී ලංකාවට ආවේණික වලිකුකුළා ජාතික පක්ෂියා වේ."),
    q("ශ්‍රී ලංකාවේ ජාතික ක්‍රීඩාව ලෙස නිල වශයෙන් පිළිගැනෙන්නේ කුමන ක්‍රීඩාවද?", "වොලිබෝල්", "ක්‍රිකට්", "එල්ලේ", "කබඩි", "1991 සිට වොලිබෝල් ක්‍රීඩාව ශ්‍රී ලංකාවේ ජාතික ක්‍රීඩාව ලෙස ප්‍රකාශිතය."),
    q("පුරවැසියෙකු හා සාමාන්‍ය නිවැසියෙකු (Resident) අතර පවතින ප්‍රධාන නෛතික වෙනස කුමක්ද?", "පුරවැසියාට ඡන්ද බලය වැනි පූර්ණ දේශපාලන අයිතීන් හිමි වීම", "නිවැසියාට පමණක් බදු ගෙවීමට සිදුවීම", "පුරවැසියාට නීති අදාළ නොවීම", "නිවැසියාට රාජ්‍ය නායක ධුරය දැරිය හැකි වීම", "ඡන්දය දීම හා රාජ්‍ය තනතුරු දැරීම වැනි දේශපාලන අයිතීන් හිමිවන්නේ පුරවැසියන්ට පමණි."),
    q("විදේශ රටකදී ශ්‍රී ලාංකික පුරවැසියෙකුට රැකවරණය හා නෛතික සහාය සපයන රාජ්‍ය ආයතනය කුමක්ද?", "ශ්‍රී ලංකා තානාපති කාර්යාලය හෝ මහ කොමසාරිස් කාර්යාලය", "විදේශ පෞද්ගලික බැංකුව", "සංචාරක හෝටල් සංගමය", "අදාළ රටේ පළාත් පාලන සභාව", "රාජ්‍යය තම විදේශගත පුරවැසියන්ගේ ආරක්ෂාව තානාපති කාර්යාල හරහා තහවුරු කරයි."),
    q("පුරවැසිභාවය අහෝසි විය හැකි නීතිමය අවස්ථාවක් වන්නේ පහත සඳහන් කුමක්ද?", "පුරවැසියෙකු සිය කැමැත්තෙන් වෙනත් රටක පුරවැසිභාවය ලබා ඉවත් වීම", "මැතිවරණයකදී පරාජිත පක්ෂයකට ඡන්දය දීම", "රජයේ පාසලකින් ඉවත්ව රැකියාවක් කිරීම", "වෙනත් දිස්ත්‍රික්කයක පදිංචියට යාම", "කැමැත්තෙන් ඉල්ලා අස්වීම (Renunciation) හෝ වංචනික ලියාපදිංචිය හෙළිවීම මත පුරවැසිභාවය අහිමි විය හැක."),
    q("ප්‍රජාතන්ත්‍රවාදී රාජ්‍යයක රාජ්‍ය සේවකයන් තම රාජකාරි ඉටුකිරීමේදී පවත්වාගත යුතු ප්‍රධාන ගුණාංගය කුමක්ද?", "දේශපාලන මධ්‍යස්ථභාවය හා අපක්ෂපාතීත්වය", "පාලක පක්ෂයේ සාමාජිකයන්ට පමණක් සේවය කිරීම", "මහජන තොරතුරු සදාකාලිකව සැඟවීම", "තීරණ ගැනීම ප්‍රමාද කිරීම", "සෑම පුරවැසියෙකුටම සමානව හා අපක්ෂපාතීව සේවා සැපයීම රාජ්‍ය සේවයේ වගකීමයි."),
    q("ජනතාවගේ කැමැත්ත නොමැතිව බලහත්කාරයෙන් රාජ්‍ය බලය අල්ලා ගැනීම ප්‍රජාතන්ත්‍රවාදයට පටහැනි වන්නේ ඇයි?", "ජනතා පරමාධිපත්‍යය උල්ලංඝනය වන බැවින්", "එමඟින් නීති පද්ධතිය සරල වන බැවින්", "රාජ්‍ය වියදම් ඉතිරි වන බැවින්", "පළාත් පාලන ආයතන ශක්තිමත් වන බැවින්", "නීත්‍යානුකූල මැතිවරණයකින් තොරව බලය ගැනීම ජනවරමට විරුද්ධ වේ."),
    q("විධිමත් ව්‍යවස්ථාවක් රටක පැවතීමෙන් සාමාන්‍ය පුරවැසියාට ලැබෙන ප්‍රධානතම වාසිය කුමක්ද?", "තම මූලික අයිතිවාසිකම් හා නිදහස නීත්‍යානුකූලව තහවුරු වීම", "කිසිදු බද්දක් නොගෙවා සිටීමට හැකි වීම", "සියලු නීතිවලින් මුක්තිය ලැබීම", "පාර්ලිමේන්තු වරප්‍රසාද හිමි වීම", "ව්‍යවස්ථාව පාලකයන්ගේ බලය සීමා කර පුරවැසි අයිතීන් සුරකියි."),
    q("පහත සඳහන් ක්‍රියා අතරින් නීතියේ ආධිපත්‍යයට අනුකූල වන්නේ කුමක්ද?", "නීති විරෝධී ක්‍රියාවකදී ඕනෑම තරාතිරමක අයෙකුට සමානව නීතිය ක්‍රියාත්මක වීම", "උසස් නිලධාරීන්ට පමණක් දඬුවමින් නිදහස ලැබීම", "පැමිණිල්ල විභාග නොකර දඬුවම් නියම කිරීම", "සැකකරුවන්ට නීතිඥ සහාය තහනම් කිරීම", "තරාතිරම නොබලා සැමට සමානව නීතිය ක්‍රියාත්මක වීම නීතියේ ආධිපත්‍යයයි."),
    q("ප්‍රජාතන්ත්‍රවාදී පාලනයක 'සාධාරණ විනිශ්චයකට ඇති අයිතිය' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "චූදිතයෙකුට ස්වාධීන අධිකරණයක විවෘත නඩු විභාගයකට ඇති අයිතිය", "වැරදිකරුවන්ට කිසිදු දඬුවමක් නොදීම", "පොලිස් නිලධාරීන්ම විනිසුරුවන් ලෙස ක්‍රියා කිරීම", "රහසිගතව දඬුවම් නියම කිරීම", "වරදකරු බව ඔප්පු වන තුරු නිර්දෝෂී ලෙස සැලකීම හා සාධාරණ විභාගයක් ලැබීම මෙයට අයත් වේ."),
    q("විරුද්ධ මත දරන්නන්ගේ අදහස් ඉවසා සිටීම පිළිබඳව ප්‍රකට ප්‍රජාතන්ත්‍රවාදී කියමන කුමන චින්තකයා හා බැඳේද?", "වෝල්ටෙයාර්", "නැපෝලියන් බොනපාට්", "ඇඩොල්ෆ් හිට්ලර්", "මුසෝලිනී", "'ඔබේ මතයට මම එකඟ නොවුවත් එය ප්‍රකාශ කිරීමේ අයිතිය රකිමි' යන්න වෝල්ටෙයාර්ගේ අදහස හා බැඳේ."),
    q("නියෝජිත ප්‍රජාතන්ත්‍රවාදී පාලනයක පාර්ලිමේන්තු මන්ත්‍රීවරුන් පත් කිරීම සඳහා යොදාගන්නා මූලික ක්‍රමය කුමක්ද?", "මහජන ඡන්දයෙන් තේරී පත්වීම", "ජනාධිපතිවරයාගේ පෞද්ගලික නම් කිරීමෙන් පමණක්", "අධිකරණ කොමිසමේ තීරණයෙන්", "රාජ්‍ය විභාග පැවැත්වීමෙන්", "මහජන නියෝජිතයන් පත්කරන්නේ නිදහස් මැතිවරණ මඟිනි."),
    q("ප්‍රජාතන්ත්‍රවාදී රාජ්‍යයක ආණ්ඩුව ගන්නා වැරදි තීරණ නිවැරදි කර ගැනීමට මහජනතාවට ඇති සාමකාමී බලපෑම් මාර්ගයක් කුමක්ද?", "මහජන පෙත්සම් හා සාමකාමී අදහස් දැක්වීම්", "රාජ්‍ය ගොඩනැගිලි ගිනි තැබීම", "විදේශ හමුදා කැඳවීම", "අධිකරණ විනිසුරුවන්ට තර්ජනය කිරීම", "පෙත්සම්, මාධ්‍ය අදහස් හා සාමකාමී විරෝධතා නීත්‍යානුකූල බලපෑම් මාර්ග වේ."),
    q("ජනාධිපති ක්‍රමයේ සහ පාර්ලිමේන්තු ක්‍රමයේ මිශ්‍රණයක් පවතින රාජ්‍යයක අග්‍රාමාත්‍යවරයාගේ කාර්යභාරය කුමක්ද?", "පාර්ලිමේන්තුවේ ආණ්ඩුව මෙහෙයවීම හා කැබිනට් කටයුතුවලට සහාය වීම", "සියලු අධිකරණ තීන්දු ලිවීම", "හමුදා සේනාධිනායක ලෙස තනිව යුද්ධ ප්‍රකාශ කිරීම", "මැතිවරණ කොමිසමේ සභාපති ලෙස ක්‍රියා කිරීම", "අර්ධ-ජනාධිපති ක්‍රමයේ ජනාධිපති හා අගමැති අතර විධායක හා ව්‍යවස්ථාදායක සම්බන්ධීකරණය පවතී."),
    q("රාජ්‍ය පාලනයේදී 'නීත්‍යානුකූලභාවය' (Legitimacy) යන්නෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "ආණ්ඩුවේ පාලන බලය ජනතාව නීත්‍යානුකූලව පිළිගැනීම", "ආණ්ඩුවට විශාල විදේශ ණය ප්‍රමාණයක් තිබීම", "පාලකයන් දීර්ඝ කාලයක් මැතිවරණ කල් දැමීම", "හමුදා බලයෙන් පමණක් පාලනය ගෙන යාම", "ජනතා කැමැත්ත හා ව්‍යවස්ථානුකූලභාවය මත ලැබෙන පිළිගැනීම Legitimacy වේ."),
    q("පුරවැසිභාවය පිළිබඳව පහත ප්‍රකාශ අතුරින් නිවැරදි ප්‍රකාශය කුමක්ද?", "පුරවැසියාට අයිතිවාසිකම් මෙන්ම රාජ්‍යයට ඉටු කළ යුතු යුතුකම්ද ඇත", "පුරවැසියාට ඇත්තේ අයිතිවාසිකම් පමණි", "පුරවැසිභාවය වයස 18න් පසුව පමණක් හිමිවේ", "පුරවැසිභාවය කිසිදු නීතියකින් නියාමනය නොවේ", "උපතේ සිටම පුරවැසිභාවය හිමිවන අතර අයිතිවාසිකම් හා යුතුකම් දෙකම ඊට ඇතුළත් වේ."),
    q("වයස අවුරුදු 18ට අඩු ශ්‍රී ලාංකික දරුවෙකු සැලකෙන්නේ කවර තත්ත්වයකද?", "අයිතිවාසිකම් හිමි ශ්‍රී ලාංකික පුරවැසියෙකු ලෙස", "රාජ්‍ය රහිත විදේශිකයෙකු ලෙස", "ඡන්ද බලය හිමි වැඩිහිටියෙකු ලෙස", "විදේශ තානාපතිවරයෙකු ලෙස", "දරුවන්ට ඡන්ද බලය නොමැති වුවද උපතින්ම ශ්‍රී ලාංකික පුරවැසිභාවය හා ආරක්ෂාව හිමිවේ."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක පාලන බලය කිසිදා එක් අයෙකුගේ පෞද්ගලික දේපළක් නොවීමට හේතුව කුමක්ද?", "බලය ජනතාවගෙන් තාවකාලික භාරයක් ලෙස ලැබෙන බැවින්", "රාජ්‍යයට ආදායම් මාර්ග නොමැති බැවින්", "අධිකරණ පද්ධතිය අහෝසි කර ඇති බැවින්", "පාර්ලිමේන්තුව වසරකට වරක් පමණක් රැස්වන බැවින්", "නියමිත නිල කාලය අවසානයේ ජනතාවට නැවත තීරණය කිරීමේ බලය පවතී."),
    q("ජාතික ආරක්ෂාව හා සමාජ සාමය ආරක්ෂා කිරීමේදී පුරවැසියෙකුගේ වගකීම කුමක්ද?", "නීතියට ගරු කරමින් නීති බලධාරීන්ට සහාය වීම", "අසත්‍ය කටකතා සමාජ මාධ්‍යවල පැතිරවීම", "පොදු නීති නොසලකා හැරීම", "පුද්ගලික වෛරය මත ගැටුම් ඇවිළවීම", "සත්‍ය තොරතුරු ලබාදීම හා නීතියට ගරු කිරීම සාමය රැකීමට ඉවහල් වේ."),
    q("ප්‍රජාතන්ත්‍රවාදයේ ප්‍රධාන පදනම් වන නිදහස හා සමානාත්මතාව රැකගැනීමට පාර්ලිමේන්තු විවාද උපකාරී වන්නේ කෙසේද?", "විවිධ ජන කොටස්වල ගැටලු හා විවේචන විවෘතව සාකච්ඡා කෙරෙන බැවින්", "සියලුම නීති රහසිගතව සම්මත කෙරෙන බැවින්", "විරුද්ධ පක්ෂවලට කතා කිරීමට ඉඩ නොදෙන බැවින්", "ප්‍රශ්න විසඳීම ප්‍රමාද කරන බැවින්", "පාර්ලිමේන්තු විවාද හංසඩ් වාර්තාවලින් මහජනතාවට විවෘත වේ."),
    q("රාජ්‍ය පාලනයේදී 'මහජන සුබසිද්ධිය' (Public Welfare) ප්‍රමුඛ වීමෙන් පෙන්නුම් කරන්නේ කුමක්ද?", "ආණ්ඩුව ජනතා යහපත උදෙසා කැපවී සිටින බව", "රටේ මැතිවරණ අහෝසි කර ඇති බව", "පෞද්ගලික අයිතිවාසිකම් සීමා කළ බව", "ව්‍යවස්ථාදායකය අක්‍රිය වූ බව", "ප්‍රජාතන්ත්‍රවාදයේ අවසන් ඉලක්කය වන්නේ සමස්ත පුරවැසියන්ගේ සුබසිද්ධියයි."),
    q("ශ්‍රී ලංකාවේ ඒකීයභාවය සුරැකීම සඳහා ව්‍යවස්ථාවේ 2 වන වගන්තිය සංශෝධනය කිරීමට අවශ්‍ය වන්නේ කුමන අනුමැතියද?", "පාර්ලිමේන්තුවේ 2/3 බහුතරය සහ ජනමත විචාරණ අනුමැතිය", "සරල බහුතර අනුමැතිය පමණි", "අග්‍රාමාත්‍යවරයාගේ අත්සන පමණි", "පළාත් සභා ආණ්ඩුකාරවරුන්ගේ අනුමැතිය", "83 වන වගන්තිය අනුව 2 වන වගන්තිය සංශෝධනයට 2/3 හා ජනමත විචාරණය අත්‍යවශ්‍ය වේ."),
    q("ව්‍යවස්ථාපිතව 'දේශපාලන බලය' හා 'පරිපාලන බලය' වෙන්කර තැබීමෙන් රාජ්‍ය සේවයට ලැබෙන වාසිය කුමක්ද?", "ආණ්ඩු මාරු වුවද රාජ්‍ය සේවා අඛණ්ඩව හා මධ්‍යස්ථව ක්‍රියාත්මක වීම", "සෑම මැතිවරණයකින් පසු සියලු නිලධාරීන් ඉවත් කිරීම", "රාජ්‍ය නිලධාරීන් දේශපාලන වේදිකාවල කතා කිරීම", "පෞද්ගලික අංශයේ බැංකු වසා දැමීම", "ස්ථිර හා අපක්ෂපාතී රාජ්‍ය සේවයක් පැවතීම පරිපාලන ස්ථාවරත්වය සුරකියි."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක ජනමත විචාරණයක් පවත්වන අවස්ථාවකදී ජනතාව සිදුකරන්නේ කුමක්ද?", "ඉදිරිපත් කර ඇති යෝජනාවට සෘජුවම 'ඔව්' හෝ 'නැත' ලෙස ඡන්දය දීම", "නව පළාත් සභා මන්ත්‍රීවරුන් තෝරාපත් කිරීම", "නව අගවිනිසුරුවරයා පත් කිරීම", "පළාත් පාලන බදු අනුපාත ගණනය කිරීම", "ජනමත විචාරණයකදී ඡන්දදායකයන් සෘජු තීරණයක් ලබා දේ."),
    q("යහපත් පුරවැසියෙකු ලෙස අන් අයගේ ආගමික හා සංස්කෘතික උත්සව කෙරෙහි දැක්විය යුතු ආකල්පය කුමක්ද?", "ගෞරවයෙන් හා සහජීවනයෙන් පිළිගැනීම", "උපහාසයෙන් බැහැර කිරීම", "නීතියෙන් තහනම් කිරීමට ඉල්ලා සිටීම", "සම්පූර්ණයෙන් නොසලකා හැරීම", "බහුසංස්කෘතික ප්‍රජාතන්ත්‍රවාදය තුළ අන්‍යෝන්‍ය ගෞරවය අත්‍යවශ්‍ය වේ."),
    q("රාජ්‍ය පාලන ක්‍රම අතුරින් 'වැඩවසම් රාජාණ්ඩු ක්‍රමය' නූතන ප්‍රජාතන්ත්‍රවාදයෙන් වෙනස් වන ප්‍රධාන කරුණ කුමක්ද?", "රාජ්‍ය බලය ජනතා කැමැත්තෙන් තොරව පරම්පරාවෙන් උරුම වීම", "මැතිවරණ කොමිසමක් විසින් රජු තේරීම", "සර්වජන ඡන්ද බලය ක්‍රියාත්මක වීම", "ලිඛිත මූලික අයිතිවාසිකම් පරිච්ඡේදයක් පැවතීම", "වැඩවසම් රාජාණ්ඩුවේ බලය පරම්පරා උරුමයෙන් රජු අත කේන්ද්‍රගත විය."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක ඕනෑම පුරවැසියෙකුට නීත්‍යානුකූලව තමන් කැමති රැකියාවක් තෝරාගැනීමේ නිදහස ලැබෙන්නේ කෙසේද?", "ව්‍යවස්ථාවෙන් තහවුරු කළ මූලික අයිතිවාසිකමක් ලෙස", "දේශපාලන පක්ෂ සාමාජිකත්වයෙන් පමණක්", "විදේශ තානාපති අනුමැතියෙන්", "පළාත් පාලන සභාපතිගේ බලපත්‍රයෙන්", "නීත්‍යානුකූල වෘත්තියක යෙදීමේ නිදහස ව්‍යවස්ථාවේ 14(1)(උ) වගන්තියෙන් සුරැකේ."),
    q("සංවර්ධිත ප්‍රජාතන්ත්‍රවාදී රටක 'නිදහස් මැතිවරණයක්' පැවැත්වීමේදී අත්‍යවශ්‍ය කොන්දේසියක් වන්නේ කුමක්ද?", "ඡන්දදායකයන්ට භීතියෙන් හා බලපෑමෙන් තොරව ඡන්දය දීමට හැකි වීම", "එක් අපේක්ෂකයෙකු පමණක් ඉදිරිපත් වීම", "ඡන්ද පත්‍රිකාවේ නම හා හැඳුනුම්පත් අංකය ප්‍රසිද්ධ කිරීම", "පාලක පක්ෂය පමණක් ඡන්ද ගණන් කිරීම", "නිදහස් හා සාධාරණ මැතිවරණයකට ස්වාධීන මැතිවරණ පරිපාලනය හා භීතියෙන් තොර පරිසරයක් අවශ්‍ය වේ."),
    q("රටේ පොදු නීති සම්පාදනයේදී හා ක්‍රියාත්මක කිරීමේදී මහජන විශ්වාසය බිඳ වැටුණහොත් ඇතිවන තත්ත්වය කුමක්ද?", "පාලන අස්ථාවරත්වය හා සමාජ නොසන්සුන්තාව", "ආර්ථික සමෘද්ධිය ක්ෂණිකව ඉහළ යාම", "රාජ්‍ය ආදායම දෙගුණ වීම", "ජාත්‍යන්තර සහයෝගීතාව ශක්තිමත් වීම", "පාලකයන් කෙරෙහි විශ්වාසය පලුදු වීම රාජ්‍ය පාලනය අඩපණ කරයි."),
    q("පුරවැසියන් තුළ 'දේශපාලන සාක්ෂරතාව' (Political Literacy) ඉහළ මට්ටමක පැවතීමෙන් සිදුවන්නේ කුමක්ද?", "පාලන ක්‍රමය හා අයිතිවාසිකම් අවබෝධ කරගෙන බුද්ධිමත්ව තීරණ ගැනීම", "දේශපාලන පක්ෂ සියල්ල වර්ජනය කිරීම", "ඡන්දය භාවිත කිරීම සම්පූර්ණයෙන් නතර කිරීම", "ව්‍යාජ ප්‍රචාරවලට පහසුවෙන් රැවටීම", "දේශපාලන අවබෝධය ඇති පුරවැසියා ප්‍රජාතන්ත්‍රවාදයේ ශක්තිමත්ම ආරක්ෂකයායි."),
    q("ශ්‍රී ලංකාවේ පළමු වරට රාජ්‍ය භාෂාව පිළිබඳ විශේෂ පනත සම්මත කරන ලද වර්ෂය කුමක්ද?", "1956", "1948", "1972", "1987", "1956 රාජ්‍ය භාෂා පනත හඳුන්වා දෙන ලද අතර පසුව 1987 දී දෙමළ භාෂාවද රාජ්‍ය භාෂාවක් විය."),
    q("1978 ව්‍යවස්ථාව අනුව පරමාධිපත්‍යය යන්නට අයත් වන ප්‍රධාන සංරචක තුන කවරේද?", "පාලන බලතල, මූලික අයිතිවාසිකම් සහ ඡන්ද බලය", "බදු අයකිරීම, යුද්ධ කිරීම සහ වෙළඳාම", "මුද්‍රණය, ප්‍රවාහනය සහ සන්නිවේදනය", "පළාත් සභා, නගර සභා සහ ගම්සභා", "4 වන වගන්තිය අනුව පරමාධිපත්‍යයට පාලන බලතල (3), මූලික අයිතිවාසිකම් හා ඡන්ද බලය අයත් වේ."),
    q("ප්‍රජාතන්ත්‍රවාදී පාලන ක්‍රමයේදී 'කැබිනට් සාමූහික වගකීම' මඟින් තහවුරු කෙරෙන්නේ කුමක්ද?", "රජයේ ප්‍රතිපත්ති තීරණ සඳහා සියලු ඇමතිවරුන් පොදුවේ වගකීම", "සෑම ඇමතිවරයෙකුම තනි තනිව පක්ෂ පිහිටුවීම", "ඇමතිවරුන් පාර්ලිමේන්තුවට පැමිණීමෙන් වැළකීම", "ජනාධිපති සමාව අවලංගු කිරීම", "කැබිනට් තීරණයකට එකඟ නොවන ඇමතිවරයෙකු ධුරයෙන් ඉල්ලා අස්විය යුතුය."),
    q("විධායක ජනාධිපති ක්‍රමයක් ක්‍රියාත්මක වන රටක විධායකයේ ස්ථාවරභාවය ඉහළ මට්ටමක පවතින්නේ ඇයි?", "ජනාධිපතිවරයා නියමිත වසර ගණනක් වෙනුවෙන් පත්වන බැවින්", "පාර්ලිමේන්තුව මාසිකව විසුරුවා හරින බැවින්", "අමාත්‍ය මණ්ඩලයක් නොමැති බැවින්", "අධිකරණ පද්ධතිය අක්‍රිය බැවින්", "පාර්ලිමේන්තු බහුතරය වෙනස් වුවද ජනාධිපති ධුර කාලය ස්ථාවරව පවතී."),
    q("ශ්‍රී ලංකා පුරවැසිභාවය උපතින් හිමිවීම සඳහා මූලිකවම සලකා බලන කොන්දේසිය කුමක්ද?", "උපදින අවස්ථාවේදී පියා හෝ මව ශ්‍රී ලංකා පුරවැසියෙකු වීම", "දෙමාපියන් රජයේ රැකියාවක් කිරීම", "ලංකාවේ බැංකු ගිණුමක් පැවතීම", "විශ්වවිද්‍යාල උපාධියක් තිබීම", "පුරවැසි පනත සංශෝධන අනුව මව හෝ පියා ශ්‍රී ලාංකික පුරවැසියෙකු නම් උපතින් පුරවැසිභාවය හිමිවේ."),
    q("රාජ්‍යයේ හා පුරවැසියාගේ අන්‍යෝන්‍ය සබඳතාව ශක්තිමත් කරන ප්‍රධානම ලේඛනය කුමක්ද?", "ආණ්ඩුක්‍රම ව්‍යවස්ථාව", "වාණිජ බැංකු ගිවිසුම", "රියදුරු බලපත්‍රය", "ව්‍යාපාර නාම ලියාපදිංචිය", "රාජ්‍යයේ බලතල හා පුරවැසියාගේ අයිතිවාසිකම් හා යුතුකම් ව්‍යවස්ථාවෙන් නියාමනය වේ."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක පාසල් අධ්‍යාපනය නොමිලේ සැපයීමෙන් ඉටුවන ප්‍රධාන ප්‍රජාතන්ත්‍රවාදී අරමුණ කුමක්ද?", "සමාජ තරාතිරම නොසලකා සෑම දරුවෙකුටම සමාන අවස්ථා සැලසීම", "විභාග ක්‍රමය සම්පූර්ණයෙන් අහෝසි කිරීම", "විදේශ භාෂා ඉගැන්වීම තහනම් කිරීම", "රාජ්‍ය සේවය අඩු කිරීම", "නිදහස් අධ්‍යාපනය සමාජ සමානාත්මතාව හා දැනුවත් පුරවැසි සමාජයක් ගොඩනගයි."),
    q("නියෝජිත ප්‍රජාතන්ත්‍රවාදයේ ප්‍රධාන දුර්වලතාවක් ලෙස ඇතැම් විට දක්නට ලැබෙන තත්ත්වය කුමක්ද?", "නියෝජිතයන් පත්වූ පසු ජනතා අවශ්‍යතා නොසලකා හැරීම", "සියලු ජනතාව එක්රැස් වී නීති සම්පාදනය කිරීම", "දේශපාලන පක්ෂ පිහිටුවීමට ඉඩ නොලැබීම", "විධායකය හා අධිකරණය අතර කිසිදු නීතියක් නොතිබීම", "මැතිවරණයෙන් පසු ඇතැම් නියෝජිතයන් ජනතාවගෙන් දුරස්ථ වීම දුර්වලතාවකි."),
    q("ලෝක ප්‍රජාතන්ත්‍රවාදී දිනය එක්සත් ජාතීන්ගේ සංවිධානය විසින් සමරනු ලබන්නේ සෑම වසරකම කවදාද?", "සැප්තැම්බර් 15", "දෙසැම්බර් 10", "ඔක්තෝබර් 24", "මැයි 01", "එක්සත් ජාතීන්ගේ මහා මණ්ඩලය සැප්තැම්බර් 15 ජාත්‍යන්තර ප්‍රජාතන්ත්‍රවාදී දිනය ලෙස ප්‍රකාශයට පත් කළේය."),
    q("ජනතා පරමාධිපත්‍යය අර්ථවත් වීම සඳහා පුරවැසියා සතු ඡන්ද බලය භාවිත කළ යුත්තේ කෙසේද?", "බුද්ධිමත්ව, ස්වාධීනව හා අල්ලසින් තොරව", "අන් අයගේ බලපෑමට යටත්ව", "පුද්ගලික වරදාන අපේක්ෂාවෙන්", "කිසිදු ප්‍රතිපත්තියක් නොබලා", "නිදහස් හා දැනුවත් ඡන්ද ප්‍රකාශනය ප්‍රජාතන්ත්‍රවාදය සුරකියි."),
    q("ශ්‍රී ලංකාවේ ප්‍රථම වරට පූර්ණ දේශපාලන නිදහස හෙවත් ජනරජ තත්ත්වය හිමිවූයේ කවර ව්‍යවස්ථාවෙන්ද?", "1972 පළමු ජනරජ ව්‍යවස්ථාවෙන්", "1931 ඩොනමෝර් ව්‍යවස්ථාවෙන්", "1833 කෝල්බෲක් ප්‍රතිසංස්කරණයෙන්", "1910 කෲව්-මැකලම් ව්‍යවස්ථාවෙන්", "1972 මැයි 22 දින බ්‍රිතාන්‍ය කිරීටයෙන් පූර්ණව වෙන්වී ජනරජයක් බවට පත්විය."),
    q("ජනරජයක් (Republic) යන්නෙහි ප්‍රධානතම ලක්ෂණය කුමක්ද?", "රාජ්‍ය නායකයා උරුමයෙන් නොව තේරී පත්වීමෙන් පත්වීම", "රජුගේ වැඩිමහල් පුත්‍රයා පාලකයා වීම", "විදේශ අධිරාජ්‍යයකට බදු ගෙවීම", "පාර්ලිමේන්තු මැතිවරණ පැවැත්වීම තහනම් වීම", "ජනරජයක රාජ්‍ය නායකයා මහජනතාවගේ හෝ නියෝජිතයන්ගේ කැමැත්තෙන් පත්වේ."),
    q("පහත සඳහන් රටවල් අතරින් 'ජනරජ' ආකෘතියට අයත් නොවන රට කුමක්ද?", "එක්සත් රාජධානිය", "ශ්‍රී ලංකාව", "ඉන්දියාව", "ප්‍රංශය", "එක්සත් රාජධානිය ව්‍යවස්ථාපිත රාජාණ්ඩුවක් වන අතර අනෙක් රටවල් ජනරජ වේ."),
    q("ප්‍රජාතන්ත්‍රවාදී ආණ්ඩු ක්‍රමයක පුරවැසියන්ට ආණ්ඩුවේ ක්‍රියාකලාපයට එරෙහිව නඩු පැවරීමට හැකි වීමෙන් තහවුරු වන්නේ කුමක්ද?", "පාලකයන්ද නීතියට යටත් බව", "රාජ්‍ය සේවය අක්‍රිය වූ බව", "ව්‍යවස්ථාදායකය අහෝසි වූ බව", "මැතිවරණ නීති අවලංගු වූ බව", "විධායකයේ හා පරිපාලනයේ අයුක්ති ක්‍රියා අධිකරණයේ අභියෝගයට ලක් කළ හැක."),
    q("විධායක බලය හා ව්‍යවස්ථාදායක බලය අතර අන්‍යෝන්‍ය සහයෝගය වැඩි වශයෙන්ම දක්නට ලැබෙන පාලන ක්‍රමය කුමක්ද?", "පාර්ලිමේන්තු කැබිනට් ක්‍රමය", "දැඩි ජනාධිපති ක්‍රමය", "හමුදා පාලන ක්‍රමය", "පරම රාජාණ්ඩු ක්‍රමය", "කැබිනට් මණ්ඩලය පාර්ලිමේන්තු මන්ත්‍රීවරුන්ගෙන්ම සමන්විත වීම ඊට හේතුවයි."),
    q("රටක අලිඛිත ව්‍යවස්ථාවක ප්‍රධාන මූලාශ්‍ර වන්නේ කවරේද?", "සම්ප්‍රදායන්, අධිකරණ තීන්දු හා පාර්ලිමේන්තු පනත්", "එක් තනි කැබිනට් පත්‍රිකාවක් පමණක්", "පළාත් සභා නියෝග පමණක්", "විදේශීය ගිවිසුම් පමණක්", "බ්‍රිතාන්‍යයේ මෙන් අලිඛිත ව්‍යවස්ථාවක් ඓතිහාසික සම්මුති හා ප්‍රඥප්ති මත රඳා පවතී."),
    q("ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 'ජනතාව' යනුවෙන් අදහස් කරන ප්‍රධාන පිරිස කවුද?", "ශ්‍රී ලංකා ජනරජයේ සමස්ත පුරවැසියන්", "පාර්ලිමේන්තු මන්ත්‍රීවරුන් පමණක්", "රාජ්‍ය අමාත්‍යාංශ ලේකම්වරුන්", "නගර සභා නගරාධිපතිවරුන්", "පරමාධිපත්‍ය බලය හිමිවන්නේ සමස්ත ශ්‍රී ලාංකික පුරවැසි ප්‍රජාවටමය."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක පුරවැසියන්ගේ භාෂා හා සංස්කෘතික අයිතීන් සුරැකීමෙන් ඇතිවන යහපත් ප්‍රතිඵලය කුමක්ද?", "ජාතික සමගිය හා සමාජ ස්ථාවරත්වය වර්ධනය වීම", "ආණ්ඩුක්‍රම ව්‍යවස්ථාව දුර්වල වීම", "විදේශ සබඳතා බිඳවැටීම", "අධිකරණ ක්‍රමය අඩපණ වීම", "සෑම ජන කොටසකටම තම අනන්‍යතාව රැකගෙන රටේ සංවර්ධනයට දායක වීමට හැකි වේ."),
    q("ආණ්ඩුවක ව්‍යවස්ථාදායක කටයුතු සඳහා සාමාන්‍ය පුරවැසියන්ට වක්‍රව දායක විය හැකි ආකාරය කුමක්ද?", "තමන් පත්කරන මන්ත්‍රීවරුන්ට අදහස් යෝජනා ඉදිරිපත් කිරීමෙන්", "පනත් කෙටුම්පත්වලට කථානායක ලෙස අත්සන් තැබීමෙන්", "රාජ්‍ය අයවැය හිතුමතේ වෙනස් කිරීමෙන්", "ශ්‍රේෂ්ඨාධිකරණ තීන්දු නිකුත් කිරීමෙන්", "නියෝජිතයන් හරහා පුරවැසි යෝජනා පාර්ලිමේන්තුවට ඉදිරිපත් කළ හැක."),
    q("යම් රාජ්‍යයක 'ආණ්ඩුව' යනු රාජ්‍යයේ අත්‍යවශ්‍ය අංගයක් වන්නේ කුමන කාර්යය ඉටුකිරීම සඳහාද?", "නීති සම්පාදනය කර රාජ්‍යයේ කටයුතු පරිපාලනය කිරීම", "රටේ භූමි ප්‍රමාණය විශාල කිරීම", "විදේශීය ආක්‍රමණ ආරාධනා කිරීම", "පුරවැසියන්ගේ අයිතීන් අහිමි කිරීම", "රාජ්‍යයේ අභිමතාර්ථ ක්‍රියාවට නංවන යාන්ත්‍රණය ආණ්ඩුවයි."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක 'නිදහස් චින්තනය' පෝෂණය වීමට අත්‍යවශ්‍ය සාධකය කුමක්ද?", "අදහස් ප්‍රකාශ කිරීමේ හා තොරතුරු ලබාගැනීමේ නිදහස", "තනි රාජ්‍ය පුවත්පතක් පමණක් පවත්වාගැනීම", "පාසල් පුස්තකාල වසා දැමීම", "මාධ්‍ය වාරණය දැඩි කිරීම", "විවිධ අදහස් හුවමාරු කරගැනීමේ නිදහස ප්‍රජාතන්ත්‍රවාදයේ පදනමයි."),
    q("පහත සඳහන් අංග අතුරින් ප්‍රජාතන්ත්‍රවාදී රාජ්‍ය පාලනයේ ලක්ෂණයක් නොවන්නේ කුමක්ද?", "මැතිවරණ පැවැත්වීම සදාකාලිකව තහනම් කිරීම", "ව්‍යවස්ථාපිත මූලික අයිතිවාසිකම් සුරැකීම", "බලතල විවිධ ආයතන අතර බෙදී තිබීම", "අධිකරණයේ ස්වාධීනත්වය පැවතීම", "නියමිත කාලීන මැතිවරණ නොමැතිව ප්‍රජාතන්ත්‍රවාදය පැවතිය නොහැක."),
    q("රටක පුරවැසිභාවය ලබාදීමේදී දැඩි නීතිමය පටිපාටියක් අනුගමනය කිරීමට ප්‍රධාන හේතුව කුමක්ද?", "ජාතික ආරක්ෂාව හා රාජ්‍ය ස්වෛරීභාවය සුරැකීම", "ජනගහනය ශුන්‍ය කිරීම", "සංචාරක ව්‍යාපාරය නතර කිරීම", "විදේශ වෙළඳාම අවසන් කිරීම", "පුරවැසිභාවය රාජ්‍ය ආරක්ෂාව හා අයිතිවාසිකම් හා බැඳුණු නෛතික තත්ත්වයකි."),
    q("ශ්‍රී ලංකාවේ සෑම පුරවැසියෙකුටම පොදුවේ ගෞරව කිරීමට නියමිත ජාතික නිදහස් දිනය කවදාද?", "පෙබරවාරි 04", "මැයි 22", "සැප්තැම්බර් 07", "ඔක්තෝබර් 24", "1948 පෙබරවාරි 04 දින ශ්‍රී ලංකාව නිදහස ලැබීම ජාතික නිදහස් දිනය ලෙස සැමරේ."),
    q("විධායක ජනාධිපති ක්‍රමයක් යටතේ 'රාජ්‍ය නායකයා' සහ 'ආණ්ඩුවේ නායකයා' යන ධුර දෙකම හොබවන්නේ කවුද?", "විධායක ජනාධිපතිවරයා", "ශ්‍රේෂ්ඨාධිකරණ අගවිනිසුරුවරයා", "පාර්ලිමේන්තු කථානායකවරයා", "මැතිවරණ කොමසාරිස්වරයා", "විධායක ජනාධිපති ක්‍රමයක ජනාධිපතිවරයා රාජ්‍යයේත් ආණ්ඩුවේත් ප්‍රධානියා වේ."),
    q("පාර්ලිමේන්තු ආණ්ඩු ක්‍රමයක 'රාජ්‍ය නායකයා' සහ 'ආණ්ඩුවේ නායකයා' ලෙස ක්‍රියා කරන දෙදෙනා කවුද?", "නාමික රාජ්‍ය නායකයා (රජු/ජනාධිපති) සහ අග්‍රාමාත්‍යවරයා", "කථානායකවරයා සහ විපක්ෂ නායකවරයා", "අගවිනිසුරු සහ නීතිපතිවරයා", "දිසාපතිවරයා සහ නගරාධිපතිවරයා", "පාර්ලිමේන්තු ක්‍රමයක ද්විත්ව විධායකයක් ලෙස නාමික නායකයා හා සැබෑ නායකයා (අගමැති) වෙන්ව සිටී."),
    q("සෘජු හා නියෝජිත ප්‍රජාතන්ත්‍රවාදය අතර ඇති ප්‍රධාන වෙනස්කම කුමක්ද?", "පුරවැසියන් තීරණ ගන්නේ සෘජුවද නැතිනම් නියෝජිතයන් හරහාද යන්න", "රටේ පිහිටි ස්වාභාවික සම්පත් ප්‍රමාණය", "ජාතික ධජයේ ඇති වර්ණ සංඛ්‍යාව", "පාසල් පද්ධතියේ ඇති ශ්‍රේණි ගණන", "සෘජු ක්‍රමයේ ජනතාව තනිව තීරණ ගන්නා අතර නියෝජිත ක්‍රමයේ ඡන්දයෙන් පත්කරන නියෝජිතයන් තීරණ ගනී."),
    q("රටක ස්ථිරව පදිංචිව සිටියද පුරවැසිභාවය නොමැති පුද්ගලයෙකු හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "විදේශිකයෙකු ලෙස", "ජාතික ලැයිස්තු මන්ත්‍රී ලෙස", "රාජ්‍ය නායකයෙකු ලෙස", "ව්‍යවස්ථා සම්පාදක ලෙස", "පුරවැසිභාවය හිමි නොවූ පුද්ගලයා එම රාජ්‍යය තුළ විදේශිකයෙකු (Alien) ලෙස සැලකේ."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක පුරවැසියන් විසින් නිසි ලෙස සමාජ යුතුකම් ඉටු කිරීමෙන් රටට ලැබෙන ප්‍රතිලාභය කුමක්ද?", "සාමකාමී හා දියුණු සමාජ පරිසරයක් ගොඩනැගීම", "නීති සම්පාදනය අනවශ්‍ය වීම", "අධිකරණ පද්ධතිය වසා දැමීම", "බදු ආදායම සම්පූර්ණයෙන් අඩු වීම", "පුරවැසි වගකීම් ඉටුකිරීම සංවර්ධනය හා සාමය වේගවත් කරයි."),
    q("දේශපාලන සමානාත්මතාව තහවුරු කිරීම සඳහා ශ්‍රී ලංකාවේ අවුරුදු 18න් ඉහළ සැමට ඡන්ද බලය ලබාදීම කුමන මූලධර්මයද?", "සර්වජන ඡන්ද බල මූලධර්මය", "සීමිත ධනපති මූලධර්මය", "ප්‍රභූ නාමයෝජනා මූලධර්මය", "වෘත්තීය සමිති මූලධර්මය", "ආදායම, අධ්‍යාපනය හෝ ස්ත්‍රී පුරුෂ භාවය මත කිසිදු වෙනසක් නොකොට ඡන්ද බලය හිමිවේ.")
  )
}
